examples.template:
MonarchGoalTree(
    goals,
    labels: MonarchGoalTreeLabels(addChild: {{addChild}}),
    onAddChild: { _ in },
    actions: { goal in
        MonarchButton(goal.parentID == nil ? {{actions.objective}} : {{actions.keyResult}}, variant: .ghost, size: .sm) {}
    }
)

examples.code:
MonarchGoalTree(
    goals,
    labels: MonarchGoalTreeLabels(addChild: "Add key result"),
    onAddChild: { _ in },
    actions: { goal in
        MonarchButton(goal.parentID == nil ? "History" : "Check in", variant: .ghost, size: .sm) {}
    }
)
